WITH ranked AS (SELECT *, RANK() OVER (PARTITION BY channel, promo_code ORDER BY ends_on) AS latest_rank FROM promotions QUALIFY latest_rank = 1) SELECT DATE_TRUNC('YEAR', ends_on) AS year_start, DATE_TRUNC('WEEK', starts_on) AS week_start, CASE WHEN discount_pct >= 0.35 THEN 'HIGH' ELSE 'LOW' END AS discount_pct_tier, STDDEV_SAMP(discount_pct) AS discount_pct_stddev, COUNT(*) AS event_count, COUNT(DISTINCT channel) AS distinct_channels, GROUPING_ID() AS grouping_id FROM ranked GROUP BY GROUPING SETS ((DATE_TRUNC('YEAR', ends_on), DATE_TRUNC('WEEK', starts_on), CASE WHEN discount_pct >= 0.35 THEN 'HIGH' ELSE 'LOW' END), (DATE_TRUNC('YEAR', ends_on), DATE_TRUNC('WEEK', starts_on)), (DATE_TRUNC('YEAR', ends_on))) ORDER BY discount_pct_stddev DESC
